// Create a promise
function delay(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

function fetchWithTimeout(url, timeoutMs = 5000) {
    return new Promise((resolve, reject) => {
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), timeoutMs);

        fetch(url, { signal: controller.signal })
            .then(response => {
                clearTimeout(timer);
                if (!response.ok) reject(new Error(`HTTP ${response.status}`));
                else resolve(response.json());
            })
            .catch(err => {
                clearTimeout(timer);
                reject(err);
            });
    });
}

// Chaining
fetchWithTimeout('/api/user')
    .then(user => fetchWithTimeout(`/api/posts/${user.id}`))
    .then(posts => console.log(posts))
    .catch(err => console.error('Request failed:', err))
    .finally(() => console.log('Request completed'));

// Promise.all - concurrent execution
const [user, posts] = await Promise.all([
    fetchWithTimeout('/api/user'),
    fetchWithTimeout('/api/posts')
]);

// Promise.allSettled - all results regardless of failure
const results = await Promise.allSettled([
    fetchWithTimeout('/api/a'),
    fetchWithTimeout('/api/b')
]);
